package com.companages.controller;
import com.companages.dto.OrganizationDtos.*; import com.companages.service.OrganizationService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/organizations") public class OrganizationController { private final OrganizationService service; public OrganizationController(OrganizationService s){service=s;} @PostMapping ResponseEntity<Response> create(@Valid @RequestBody CreateRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(service.create(r));} @GetMapping List<Response> list(){return service.list();} @GetMapping("/{id}") Response get(@PathVariable Long id){return service.get(id);} @PutMapping("/{id}") Response update(@PathVariable Long id,@Valid @RequestBody UpdateRequest r){return service.update(id,r);} @DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable Long id){service.delete(id);} }
